  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "带着熟悉的神情笑吧"
        },
        {
          "id": "C1-02",
          "zh": "无底的恐惧在心中"
        },
        {
          "id": "C1-03",
          "zh": "给我平凡普通的爱吧"
        },
        {
          "id": "C1-04",
          "zh": "You know me"
        },
        {
          "id": "C1-05",
          "zh": "装作懂得跳着舞吗"
        },
        {
          "id": "C1-06",
          "zh": "心底被填满了吗"
        },
        {
          "id": "C1-07",
          "zh": "别放开我别停下啊"
        },
        {
          "id": "C1-08",
          "zh": "并非独自一人啊"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "就用那副 了然的笑脸"
        },
        {
          "id": "C1-02",
          "zh": "深不见底 恐惧漫上来"
        },
        {
          "id": "C1-03",
          "zh": "给我一份 平庸无奇的爱"
        },
        {
          "id": "C1-04",
          "zh": "你懂我"
        },
        {
          "id": "C1-05",
          "zh": "装作懂了 跳着这支舞"
        },
        {
          "id": "C1-06",
          "zh": "心底深处 被填满了吗"
        },
        {
          "id": "C1-07",
          "zh": "别放开我 别停下脚步"
        },
        {
          "id": "C1-08",
          "zh": "你不是一个人"
        }
      ]
    }
  ]
}

